body:
最近在学 RK3588 平台的 Linux 驱动开发。相比单片机直接操作寄存器，Linux 驱动多了一层"规矩"，但这层规矩让硬件管理变得可维护。本文用最小例子走通字符设备全流程。
最小字符设备骨架
#include <linux/module.h>
#include <linux/fs.h>
#include <linux/cdev.h>
#include <linux/device.h>
#define DEV_NAME "myedge_dev"
static int major;
static struct class *my_class;
static struct cdev my_cdev;
static int my_open(struct inode *inode, struct file *filp)
{
pr_info("myedge: device opened\n");
return 0;
}
static ssize_t my_read(struct file *filp, char __user *buf,
size_t count, loff_t *ppos)
{
char msg[] = "hello from kernel\n";
return simple_read_from_buffer(buf, count, ppos, msg, sizeof(msg));
}
static struct file_operations fops = {
.owner = THIS_MODULE,
.open = my_open,
.read = my_read,
};
static int __init my_init(void)
{
dev_t devno;
alloc_chrdev_region(&devno, 0, 1, DEV_NAME);
major = MAJOR(devno);
cdev_init(&my_cdev, &fops);
cdev_add(&my_cdev, devno, 1);
// 自动创建 /dev 节点，不需要手动 mknod
my_class = class_create(DEV_NAME);
device_create(my_class, NULL, devno, NULL, DEV_NAME);
pr_info("myedge: loaded, major=%d\n", major);
return 0;
}
static void __exit my_exit(void)
{
dev_t devno = MKDEV(major, 0);
device_destroy(my_class, devno);
class_destroy(my_class);
cdev_del(&my_cdev);
unregister_chrdev_region(devno, 1);
}
module_init(my_init);
module_exit(my_exit);
MODULE_LICENSE("GPL");
Makefile：
obj-m += myedge.o
KDIR := /path/to/rk3588/kernel
PWD := $(shell pwd)
all:
make -C $(KDIR) M=$(PWD) ARCH=arm64 CROSS_COMPILE=aarch64-linux-gnu- modules
设备树：硬件描述与驱动分离
驱动里不应硬编码 GPIO 编号，资源由设备树描述：
myedge {
compatible = "shiyikun,myedge";
led-gpios = <&gpio3 RK_PC5 GPIO_ACTIVE_HIGH>;
status = "okay";
};
驱动侧通过 of API 获取资源：
static int my_probe(struct platform_device *pdev)
{
struct device_node *np = pdev->dev.of_node;
int gpio;
gpio = of_get_named_gpio(np, "led-gpios", 0);
if (!gpio_is_valid(gpio)) {
dev_err(&pdev->dev, "invalid led-gpios\n");
return -EINVAL;
}
gpio_request(gpio, "myedge_led");
gpio_direction_output(gpio, 0);
return 0;
}
static const struct of_device_id my_of_match[] = {
{ .compatible = "shiyikun,myedge" },
{ /* sentinel */ }
};
MODULE_DEVICE_TABLE(of, my_of_match);
compatible 字符串是设备树节点与驱动匹配的唯一纽带——这个名字必须两边完全一致。
调试技巧
dmesg -w 实时看 pr_info 输出
cat /proc/device-tree/myedge/status 确认节点已启用
ls /sys/class/myedge_dev 确认 class 创建成功
单片机思维 vs Linux 思维
最大的转变是：单片机里"我的程序拥有整个硬件"，Linux 里"内核统一管理硬件，驱动只是服务员"。理解了这层边界，pinmux、时钟、电源域这些概念就都顺了。下一步计划写一个 I2C 子系统下的传感器驱动。

在四轴无人机飞控项目中，我选择基于 STM32F103 裸机开发，而不是直接上 FreeRTOS。原因有两个：一是飞控任务数量少且实时性要求明确，裸机调度足够；二是想彻底搞清楚"操作系统到底在干什么"。
为什么需要调度框架
裸机开发最常见的问题是 while(1) 大循环里堆满各种功能：传感器采集、姿态解算、PID 控制、无线通信……一旦某个任务耗时变长，其他任务全部被阻塞，飞控直接失控。
一个最小可用的调度框架需要解决三件事：
任务按固定周期执行（如姿态解算 500Hz、遥控解析 50Hz）
任务之间互不阻塞（单个任务超时可以被检出）
CPU 负载可观测（知道还剩多少余量）
任务表设计
核心思路是"函数指针 + 周期计数"，用结构体数组描述所有任务：
typedef struct {
void (*task_func)(void); // 任务入口
uint32_t period_ms; // 执行周期
uint32_t last_run; // 上次执行时刻
uint32_t max_cost_us; // 历史最大耗时
const char *name; // 任务名（调试用）
} task_t;
static task_t task_table[] = {
{ task_attitude_update, 2, 0, 0, "attitude" }, // 500Hz 姿态解算
{ task_pid_control, 2, 0, 0, "pid" }, // 500Hz 控制输出
{ task_nrf24_receive, 20, 0, 0, "nrf24" }, // 50Hz 遥控接收
{ task_battery_check, 100, 0, 0, "battery" }, // 10Hz 电压检测
{ task_led_heartbeat, 500, 0, 0, "led" }, // 2Hz 心跳灯
};
#define TASK_NUM (sizeof(task_table) / sizeof(task_t))
调度循环与耗时统计
主循环遍历任务表，到期的任务立即执行，并用 DWT 周期计数器统计耗时：
void scheduler_run(void)
{
for (uint8_t i = 0; i < TASK_NUM; i++) {
uint32_t now = HAL_GetTick();
if (now - task_table[i].last_run >= task_table[i].period_ms) {
task_table[i].last_run = now;
uint32_t start = DWT->CYCCNT;
task_table[i].task_func();
uint32_t cost = (DWT->CYCCNT - start) / (SystemCoreClock / 1000000U);
if (cost > task_table[i].max_cost_us) {
task_table[i].max_cost_us = cost; // 记录最差情况
}
}
}
}
使用 DWT 前需要在初始化中使能：
void dwt_init(void)
{
CoreDebug->DEMCR |= CoreDebug_DEMCR_TRCENA_Msk;
DWT->CYCCNT = 0;
DWT->CTRL |= DWT_CTRL_CYCCNTENA_Msk;
}
实测数据与结论
在 72MHz 的 STM32F103 上实测：
任务 周期 平均耗时 最大耗时
姿态解算（含四元数更新） 2ms 180μs 240μs
双环 PID 2ms 45μs 60μs
NRF24L01 接收解析 20ms 90μs 150μs
总负载约 15%，余量充足。关键经验：周期任务的单次耗时必须远小于周期，否则要考虑拆分状态机或上 RTOS。这套框架后来也被我复用到了智能手表项目中，配合 LVGL 的 lv_timer_handler 一起工作得很好。

姿态解算是飞控的核心。本文记录我在四轴无人机项目中，基于 MPU6050 六轴传感器实现姿态角解算的完整过程，最终姿态角误差稳定在 ±1.5° 以内。
硬件链路
MPU6050 通过 I2C 与 STM32F103 通信，挂载在 I2C1（PB6/PB7），地址 0x68。上电后先做三件事：
void mpu6050_init(void)
{
mpu_write_reg(0x6B, 0x00); // 解除睡眠
mpu_write_reg(0x1B, 0x18); // 陀螺仪量程 ±2000°/s
mpu_write_reg(0x1C, 0x08); // 加速度计量程 ±4g
mpu_write_reg(0x1A, 0x03); // DLPF 低通滤波 44Hz
}
踩坑记录：DLPF 带宽设太高会把电机振动噪声直接放进来，设太低又会引入相位延迟。44Hz 是悬停稳定性与响应速度之间比较平衡的点。
四元数姿态更新
直接用欧拉角积分会遇到万向锁，所以采用四元数表示姿态。每次采样后用一阶龙格库塔法更新四元数：
void quaternion_update(quat_t *q, float gx, float gy, float gz, float dt)
{
float q0 = q->q0, q1 = q->q1, q2 = q->q2, q3 = q->q3;
float dq0 = 0.5f * (-q1 * gx - q2 * gy - q3 * gz) * dt;
float dq1 = 0.5f * ( q0 * gx + q2 * gz - q3 * gy) * dt;
float dq2 = 0.5f * ( q0 * gy - q1 * gz + q3 * gx) * dt;
float dq3 = 0.5f * ( q0 * gz + q1 * gy - q2 * gx) * dt;
q->q0 += dq0; q->q1 += dq1;
q->q2 += dq2; q->q3 += dq3;
quat_normalize(q); // 必须归一化，否则误差累积发散
}
陀螺仪零偏校准放在上电静止阶段，采集 500 帧取平均：
static float gyro_bias[3] = {0};
void gyro_calibrate(void)
{
int16_t raw[3];
for (int i = 0; i < 500; i++) {
mpu_read_gyro_raw(raw);
for (int j = 0; j < 3; j++) gyro_bias[j] += raw[j];
delay_ms(2);
}
for (int j = 0; j < 3; j++) gyro_bias[j] /= 500.0f;
}
卡尔曼滤波降噪
单纯积分会漂移，需要用加速度计做观测修正。对每个姿态角建立一维卡尔曼滤波器：
float kalman_update(kalman_t *kf, float angle_measured, float gyro_rate, float dt)
{
// 预测
kf->angle += (gyro_rate - kf->bias) * dt;
kf->P[0][0] += dt * (dt * kf->P[1][1] - kf->P[0][1] - kf->P[1][0] + kf->Q_angle);
kf->P[0][1] -= dt * kf->P[1][1];
kf->P[1][0] -= dt * kf->P[1][1];
kf->P[1][1] += kf->Q_bias * dt;
// 更新
float S = kf->P[0][0] + kf->R_measure;
float K0 = kf->P[0][0] / S;
float K1 = kf->P[1][0] / S;
float y = angle_measured - kf->angle;
kf->angle += K0 * y;
kf->bias += K1 * y;
// ... P 矩阵更新略
return kf->angle;
}
调参经验：Q_angle 控制对陀螺仪的信任度，R_measure 控制对加速度计的信任度。振动大的机架需要适当增大 R_measure。
效果
静态漂移：< 0.1°/min
动态误差：< ±1.5°（剧烈机动时）
更新频率：500Hz
下篇文章会讲基于这个姿态数据的双环 PID 控制器设计。

这是我大三上学期的项目：一块基于 ESP32-S3 的多功能智能手表，支持数字时钟、消息通知、天气显示。本文复盘其中最有价值的几个技术决策。
为什么是 LVGL
ESP32-S3 没有强大的 GPU，但 LVGL（Light and Versatile Graphics Library）在 MCU 上的表现足够好：
纯 C 编写，移植只需要实现一个 flush 回调
自带事件系统、动画引擎、样式系统
支持部分刷新，降低 SPI 屏幕的带宽压力
移植核心代码：
static void disp_flush(lv_disp_drv_t *drv, const lv_area_t *area, lv_color_t *color_map)
{
st7789_push_pixels(area->x1, area->y1, area->x2, area->y2, (uint16_t *)color_map);
lv_disp_flush_ready(drv); // 必须调用，否则 LVGL 卡死
}
void lvgl_port_init(void)
{
lv_init();
static lv_disp_draw_buf_t draw_buf;
static lv_color_t buf[240 * 40]; // 40 行缓冲区，约 19KB
lv_disp_draw_buf_init(&draw_buf, buf, NULL, 240 * 40);
static lv_disp_drv_t disp_drv;
lv_disp_drv_init(&disp_drv);
disp_drv.draw_buf = &draw_buf;
disp_drv.flush_cb = disp_flush;
disp_drv.hor_res = 240;
disp_drv.ver_res = 240;
lv_disp_drv_register(&disp_drv);
}
事件驱动的界面导航
手表有多个界面（表盘、通知、天气、设置），用裸 if-else 管理会迅速失控。我设计了一个简单的页面栈：
typedef struct {
void (*create)(lv_obj_t *parent);
void (*destroy)(void);
} page_ops_t;
static const page_ops_t *page_stack[8];
static int stack_top = -1;
void page_push(const page_ops_t *page)
{
if (stack_top >= 0) page_stack[stack_top]->destroy();
page_stack[++stack_top] = page;
page->create(lv_scr_act());
}
void page_pop(void)
{
if (stack_top <= 0) return;
page_stack[stack_top--]->destroy();
page_stack[stack_top]->create(lv_scr_act());
}
配合 LVGL 的手势事件，左右滑动切换页面、下滑返回，导航逻辑非常清晰。
内存优化：最痛的一课
ESP32-S3 的 SRAM 只有 512KB，中文全字库根本放不下。优化手段：
字体裁剪：用 LVGL 官方的 font converter，只导出界面实际用到的 200 多个汉字，从 2MB 压到 60KB
图片转 C 数组 + RLE 压缩：天气图标用 LV_IMG_CF_TRUE_COLOR_CHROMA_KEYED，体积减半
图片放 Flash：所有静态资源声明为 const，链接到外部 Flash，不占 RAM
// 只包含用到的字符
lv_font_t my_font_cn = {
.unicode_first = 0x4E00, .unicode_last = 0x9FA5,
// 通过 range + glyph_id 映射裁剪后的字形
};
WiFi 数据通道
手表通过 WiFi 连接上位机，接收消息通知和天气数据，协议用简单的 JSON over TCP：
{"type": "weather", "temp": 26, "icon": "sunny", "city": "太原"}
接收任务用 FreeRTOS 独立任务运行（ESP-IDF 环境），收到数据后通过 lv_port_sem 保护地更新 UI。
总结
这个项目让我深刻理解：资源受限环境下的 UI 开发，本质上是一场内存与性能的权衡艺术。LVGL 的事件驱动架构值得学习，这套页面栈模式后来也被我用到了其他项目中。

四轴无人机的遥控链路如果延迟大、丢包高，飞得再稳的 PID 也救不回来。本文记录我基于 NRF24L01 设计的 2.4GHz 通信协议。
硬件与基础配置
NRF24L01 通过 SPI 与 STM32 连接，关键初始化参数：
void nrf24_init(void)
{
nrf_write_reg(NRF_REG_SETUP_AW, 0x03); // 5 字节地址
nrf_write_reg(NRF_REG_SETUP_RETR, 0x1F); // 重传 500μs，最多 15 次
nrf_write_reg(NRF_REG_RF_CH, 40); // 2.440GHz 信道
nrf_write_reg(NRF_REG_RF_SETUP, 0x0F); // 2Mbps，0dBm 发射功率
nrf_write_reg(NRF_REG_CONFIG, 0x0E); // CRC 16bit，使能接收中断
}
为什么选 2Mbps：空中速率越高，单包占用时间越短，被 WiFi 干扰碰撞的概率越低，实测 2Mbps 下遥控延迟约 8ms。
自定义帧格式
一包 32 字节（NRF24L01 最大有效载荷），布局如下：
偏移 字段 长度 说明
0 帧头 1B 固定 0xA5
1 类型 1B 0x01=遥控，0x02=PID 调参
2-9 通道数据 8B 4 通道 × uint16（油门/横滚/俯仰/偏航）
10-28 扩展数据 19B PID 参数或预留
29 序号 1B 丢包统计
30-31 CRC16 2B 校验
解析代码：
typedef struct __attribute__((packed)) {
uint8_t header; // 0xA5
uint8_t type;
uint16_t ch[4]; // 四通道
uint8_t payload[19];
uint8_t seq;
uint16_t crc16;
} radio_frame_t;
bool radio_parse(const uint8_t *buf, radio_frame_t *frame)
{
memcpy(frame, buf, sizeof(radio_frame_t));
if (frame->header != 0xA5) return false;
return crc16_calc((uint8_t *)frame, 30) == frame->crc16;
}
注意 __attribute__((packed)) 防止结构体对齐填充导致帧布局错乱。
PID 参数动态调节
调试期最痛苦的是每改一次 PID 都要重新烧录。我在协议里加了调参帧：上位机下发 0x02 类型帧，飞控在线更新参数并回传确认：
void handle_tune_frame(const radio_frame_t *f)
{
float kp, ki, kd;
memcpy(&kp, &f->payload[0], 4);
memcpy(&ki, &f->payload[4], 4);
memcpy(&kd, &f->payload[8], 4);
pid_set_gains(&pid_roll, kp, ki, kd);
radio_send_ack(f->seq); // 回传确认
}
配合地面站实时曲线，悬停调试效率提升了至少 5 倍。
抗干扰与失控保护
序号检测：连续丢包 10 帧（约 200ms）判定失控，油门渐变到 0 并尝试降落
跳频预留：固定信道受干扰严重时，可按约定序列切换 RF_CH
接收中断：用 IRQ 引脚触发 EXTI，避免轮询浪费 SPI 带宽
实测
端到端延迟：约 8ms（含飞控解析）
开阔地距离：> 200m（0dBm + PCB 天线）
失控保护触发到安全降落：< 3s
这套协议结构简单但够用，后续如果要上 MAVLink，帧解析层可以直接替换。

PID 是嵌入式控制里"最简单也最困难"的算法——公式三行就能写完，调参能调一个月。本文结合四轴无人机项目，把 PID 的理论、实现与调参串一遍。
两种实现形式
位置式 PID
输出直接是控制量的绝对值：
float pid_positional(pid_t *pid, float setpoint, float measured, float dt)
{
float error = setpoint - measured;
pid->integral += error * dt;
pid->integral = clamp(pid->integral, -pid->i_max, pid->i_max); // 抗积分饱和
float derivative = (error - pid->prev_error) / dt;
pid->prev_error = error;
return pid->kp * error + pid->ki * pid->integral + pid->kd * derivative;
}
增量式 PID
输出是控制量的增量，适合电机类执行器：
float pid_incremental(pid_t *pid, float setpoint, float measured)
{
float error = setpoint - measured;
float delta = pid->kp * (error - pid->prev_error)
+ pid->ki * error
+ pid->kd * (error - 2 * pid->prev_error + pid->prev_prev_error);
pid->prev_prev_error = pid->prev_error;
pid->prev_error = error;
return delta;
}
怎么选：
位置式：输出直观，限幅简单，适合阀门、舵机、温度控制
增量式：积分天然有界，手动/自动切换无扰，适合电机调速
飞控中我用的是位置式 + 积分限幅，因为电机需要的是绝对油门值
串级双环：飞控的正确打开方式
单环 PID 直接控角度，响应慢且容易振荡。工业和飞控的标准做法是串级控制：
角度设定 → [角度环 PID] → 角速度设定 → [角速度环 PID] → 电机输出
(外环, 慢) (内环, 快)
外环（角度环）：输入期望角度与实际角度的误差，输出期望角速度，100-250Hz
内环（角速度环）：跟踪期望角速度，直接输出电机控制量，500Hz
void control_update(attitude_t *att, rc_cmd_t *rc, float dt)
{
// 外环：角度误差 → 期望角速度
float roll_rate_sp = pid_positional(&pid_angle_roll,
rc->roll_angle, att->roll, dt);
float pitch_rate_sp = pid_positional(&pid_angle_pitch,
rc->pitch_angle, att->pitch, dt);
// 内环：角速度误差 → 电机控制量
float roll_out = pid_positional(&pid_rate_roll,
roll_rate_sp, att->gyro_x, dt);
float pitch_out = pid_positional(&pid_rate_pitch,
pitch_rate_sp, att->gyro_y, dt);
motor_mix(rc->throttle, roll_out, pitch_out, 0);
}
内环用陀螺仪直接测得的角速度，响应快、抗扰强；外环保证角度精度。这是悬停稳定的关键。
调参方法论
我的调参顺序（内环优先）：
内环 P：逐渐增大直到机身开始高频振荡，回退到 60%
内环 D：抑制振荡余波，注意 D 会放大陀螺仪噪声，噪声大时先滤波
内环 I：消除静差（如重心偏移导致的持续倾斜），宁小勿大
外环 P：只用一个 P 通常就够，决定角度跟踪的"刚度"
经验之谈：90% 的"PID 调不好"其实是机械问题——机架松动、电机不一致、传感器振动。先检查硬件，再怀疑参数。
常见坑
积分饱和：大机动后回正过冲严重 → 加积分限幅或条件积分
微分噪声：D 项直接对角度微分会把传感器噪声放大 → 对测量值微分（微分先行）或加低通滤波
dt 不稳定：用变量 dt 而不是写死，调度抖动会直接影响 I/D 项
PID 本身只是起点，后续可以探索 LQR、ADRC，但先把这套经典串级玩透，手感就建立起来了。
